struct Hop: Codable { let name: String; let at: Date }
struct Envelope<Payload: Codable>: Codable {
    var payload: Payload
    var hops: [Hop] = []
}

func via<P>(_ e: Envelope<P>, _ component: String) -> Envelope<P> {
    var out = e                       // value copy: branches cannot alias one history
    out.hops.append(Hop(name: component, at: Date()))
    return out
}
